import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';

export const MAX_ATTEMPTS = 3;
export const HEARTBEAT_FRESH_MS = 3000;

/** Opens the SQLite database shared by the server and worker processes. */
export function openDatabase(path: string = process.env.DATABASE_PATH || 'data/jobs.db'): DatabaseSync {
  if (path !== ':memory:') mkdirSync(dirname(path), { recursive: true });
  const db = new DatabaseSync(path);
  // busy_timeout first: switching to WAL takes a brief exclusive lock, and the server and worker
  // open the same database at once, so the loser must wait rather than fail.
  db.exec('PRAGMA busy_timeout = 5000;');
  db.exec('PRAGMA journal_mode = WAL;');
  db.exec('PRAGMA synchronous = NORMAL;');
  db.exec(`
    CREATE TABLE IF NOT EXISTS jobs (
      seq INTEGER PRIMARY KEY AUTOINCREMENT,
      id TEXT NOT NULL UNIQUE,
      status TEXT NOT NULL CHECK (status IN ('queued','running','completed','failed')),
      input TEXT NOT NULL,
      steps INTEGER NOT NULL,
      fail_attempts INTEGER NOT NULL,
      attempts INTEGER NOT NULL DEFAULT 0,
      progress INTEGER NOT NULL DEFAULT 0,
      output TEXT,
      error TEXT,
      idempotency_key TEXT UNIQUE,
      payload_fingerprint TEXT,
      run_at INTEGER NOT NULL,
      lease_owner TEXT,
      lease_until INTEGER,
      created_at INTEGER NOT NULL,
      updated_at INTEGER NOT NULL
    );
    CREATE INDEX IF NOT EXISTS jobs_pick ON jobs (status, run_at, seq);
    CREATE TABLE IF NOT EXISTS worker_heartbeat (
      worker_id TEXT PRIMARY KEY,
      beat_at INTEGER NOT NULL
    );
  `);
  return db;
}

export interface JobRow {
  seq: number;
  id: string;
  status: string;
  input: string;
  steps: number;
  fail_attempts: number;
  attempts: number;
  progress: number;
  output: string | null;
  error: string | null;
  created_at: number;
  updated_at: number;
}

export function toJob(row: JobRow) {
  return {
    id: row.id,
    status: row.status,
    input: row.input,
    steps: row.steps,
    failAttempts: row.fail_attempts,
    attempts: row.attempts,
    progress: { completed: row.progress, total: row.steps },
    result: row.status === 'completed' && row.output !== null ? { output: row.output } : null,
    error: row.status === 'failed' ? row.error : null,
    createdAt: new Date(row.created_at).toISOString(),
    updatedAt: new Date(row.updated_at).toISOString(),
  };
}

/** Runs fn inside BEGIN IMMEDIATE ... COMMIT, rolling back on error. */
export function transaction<T>(db: DatabaseSync, fn: () => T): T {
  db.exec('BEGIN IMMEDIATE');
  try {
    const result = fn();
    db.exec('COMMIT');
    return result;
  } catch (err) {
    try {
      db.exec('ROLLBACK');
    } catch {
      // ignore
    }
    throw err;
  }
}

