import { setTimeout as sleep } from 'node:timers/promises';
import { randomUUID } from 'node:crypto';
import { openDatabase, transaction, MAX_ATTEMPTS, type JobRow } from './db.ts';

const STEP_MS = 100;
const RETRY_DELAY_MS = 500;
const LEASE_MS = 3000;
const POLL_MS = 150;
const HEARTBEAT_MS = 500;

const db = openDatabase();
const workerId = randomUUID();
let stopping = false;
let wake: (() => void) | null = null;

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
    wake?.();
  });
}

const beatStmt = db.prepare(
  'INSERT INTO worker_heartbeat (worker_id, beat_at) VALUES (?, ?) ON CONFLICT(worker_id) DO UPDATE SET beat_at = excluded.beat_at',
);
function heartbeat(): void {
  try {
    beatStmt.run(workerId, Date.now());
    db.prepare('DELETE FROM worker_heartbeat WHERE beat_at < ?').run(Date.now() - 60_000);
  } catch (err) {
    console.error('heartbeat failed', err);
  }
}
heartbeat();
const hbTimer = setInterval(heartbeat, HEARTBEAT_MS);

/** Interruptible sleep: resolves early when stopping. */
async function pause(ms: number): Promise<void> {
  if (stopping) return;
  await new Promise<void>((resolve) => {
    const t = setTimeout(() => {
      wake = null;
      resolve();
    }, ms);
    wake = () => {
      clearTimeout(t);
      wake = null;
      resolve();
    };
  });
}

/**
 * Atomically claims the next runnable job: a queued job whose retry time has come, or a running job
 * whose lease expired (its worker died). Oldest first.
 */
function claim(): JobRow | null {
  return transaction(db, () => {
