import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { openDatabase, toJob, transaction, HEARTBEAT_FRESH_MS, type JobRow } from './db.ts';

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');
const MAX_BODY = 1024 * 1024;
const KEY_RE = /^[A-Za-z0-9_-]{1,128}$/;

interface FieldError {
  field: string;
  message: string;
}

class HttpError extends Error {
  constructor(
    public status: number,
    public code: string,
    message: string,
    public fields?: FieldError[],
  ) {
    super(message);
  }
}

function send(res: ServerResponse, status: number, body: unknown, headers: Record<string, string> = {}): void {
  const payload = JSON.stringify(body);
  res.writeHead(status, {
    'content-type': 'application/json; charset=utf-8',
    'cache-control': 'no-store',
    'content-length': Buffer.byteLength(payload),
    ...headers,
  });
  res.end(payload);
}

function sendError(res: ServerResponse, err: HttpError, headers: Record<string, string> = {}): void {
  const error: Record<string, unknown> = { code: err.code, message: err.message };
  if (err.fields) error.fields = err.fields;
  else if (err.code === 'invalid_request') error.fields = [];
  send(res, err.status, { error }, headers);
}

function readBody(req: IncomingMessage): Promise<string> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY) tooLarge = true;
      else chunks.push(chunk);
    });
    req.on('end', () => {
      if (tooLarge) reject(new HttpError(413, 'payload_too_large', 'Request body is too large.'));
      else resolve(Buffer.concat(chunks).toString('utf8'));
    });
    req.on('error', reject);
  });
}

function isJsonContentType(header: string | undefined): boolean {
  if (!header) return false;
  const type = header.split(';')[0]!.trim().toLowerCase();
  return type === 'application/json' || (type.startsWith('application/') && type.endsWith('+json'));
}

interface Payload {
  input: string;
  steps: number;
  failAttempts: number;
}

function validate(req: IncomingMessage, raw: string): { payload: Payload; key: string | null } {
  const fields: FieldError[] = [];
  const keyHeader = req.headers['idempotency-key'];
  let key: string | null = null;
  if (keyHeader !== undefined) {
    const k = Array.isArray(keyHeader) ? keyHeader.join(',') : keyHeader;
    if (!KEY_RE.test(k)) {
      fields.push({ field: 'Idempotency-Key', message: 'Must match ^[A-Za-z0-9_-]{1,128}$.' });
    } else key = k;
  }
  const fail = (): never => {
    throw new HttpError(400, 'invalid_request', 'The request is invalid.', fields);
  };

  if (!isJsonContentType(req.headers['content-type'])) {
    fields.push({ field: 'body', message: 'Content-Type must be application/json.' });
    fail();
  }
  let body: unknown;
  try {
    body = JSON.parse(raw);
  } catch {
    fields.push({ field: 'body', message: 'Body must be valid JSON.' });
    fail();
  }
  if (typeof body !== 'object' || body === null || Array.isArray(body)) {
    fields.push({ field: 'body', message: 'Body must be a JSON object.' });
    fail();
  }
  const obj = body as Record<string, unknown>;
  for (const name of Object.keys(obj)) {
    if (!['input', 'steps', 'failAttempts'].includes(name)) {
      fields.push({ field: name, message: 'Unknown field.' });
    }
  }
  const input = obj.input;
  if (input === undefined) fields.push({ field: 'input', message: 'input is required.' });
  else if (typeof input !== 'string') fields.push({ field: 'input', message: 'input must be a string.' });
  else if (input.length < 1 || input.length > 1000) {
    fields.push({ field: 'input', message: 'input must be 1 to 1000 characters.' });
  } else if (input.trim() === '') fields.push({ field: 'input', message: 'input must not be only whitespace.' });

  const intField = (name: string, min: number, max: number, def: number): number => {
    const v = obj[name];
    if (v === undefined) return def;
    if (typeof v !== 'number' || !Number.isInteger(v) || v < min || v > max) {
      fields.push({ field: name, message: `${name} must be an integer from ${min} to ${max}.` });
      return def;
    }
    return v;
  };
  const steps = intField('steps', 1, 20, 5);
  const failAttempts = intField('failAttempts', 0, 5, 0);
  if (fields.length > 0) fail();
  return { payload: { input: input as string, steps, failAttempts }, key };
}

function getJobRow(id: string): JobRow | undefined {
  return db.prepare('SELECT * FROM jobs WHERE id = ?').get(id) as JobRow | undefined;
}

function createJob(payload: Payload, key: string | null): { status: number; job: JobRow } {
  const fingerprint = JSON.stringify([payload.input, payload.steps, payload.failAttempts]);
  return transaction(db, () => {
    if (key !== null) {
      const existing = db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?').get(key) as
        | (JobRow & { payload_fingerprint: string })
        | undefined;
      if (existing) {
        if (existing.payload_fingerprint === fingerprint) return { status: 200, job: existing };
        throw new HttpError(
          409,
          'idempotency_conflict',
          'This Idempotency-Key was already used with a different payload.',
        );
      }
    }
    const now = Date.now();
    const id = randomUUID();
    db.prepare(
      `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, progress, idempotency_key, payload_fingerprint, run_at, created_at, updated_at)
       VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, ?, ?, ?, ?)`,
    ).run(id, payload.input, payload.steps, payload.failAttempts, key, key === null ? null : fingerprint, now, now, now);
    return { status: 201, job: getJobRow(id)! };
  });
}

function workerUp(): boolean {
  const row = db.prepare('SELECT MAX(beat_at) AS beat FROM worker_heartbeat').get() as { beat: number | null };
  return row.beat !== null && Date.now() - row.beat <= HEARTBEAT_FRESH_MS;
}

function methodNotAllowed(allowed: string[]): never {
  throw Object.assign(new HttpError(405, 'method_not_allowed', 'Method not allowed.'), { allow: allowed.join(', ') });
}

async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  const method = req.method ?? 'GET';
  const isGet = method === 'GET' || method === 'HEAD';

  if (pathname === '/') {
    if (!isGet) methodNotAllowed(['GET']);
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8', 'cache-control': 'no-store' });
    res.end(method === 'HEAD' ? undefined : uiHtml);
    return;
  }
  if (pathname === '/health') {
    if (!isGet) methodNotAllowed(['GET']);
    return send(res, 200, { status: 'ok', worker: workerUp() ? 'up' : 'down' });
  }
  if (pathname === '/api/jobs') {
    if (method === 'POST') {
      const raw = await readBody(req);
      const { payload, key } = validate(req, raw);
      const { status, job } = createJob(payload, key);
      return send(res, status, toJob(job));
    }
    if (!isGet) methodNotAllowed(['GET', 'POST']);
    const rows = db.prepare('SELECT * FROM jobs ORDER BY seq DESC').all() as unknown as JobRow[];
    return send(res, 200, { jobs: rows.map(toJob) });
  }
  const m = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (m) {
    if (!isGet) methodNotAllowed(['GET']);
    let id: string;
    try {
      id = decodeURIComponent(m[1]!);
    } catch {
      throw new HttpError(404, 'not_found', 'Job not found.');
    }
    const row = getJobRow(id);
    if (!row) throw new HttpError(404, 'not_found', 'Job not found.');
    return send(res, 200, toJob(row));
  }
  throw new HttpError(404, 'not_found', 'Not found.');
}

const port = Number(process.env.PORT || 3000);
const server = createServer((req, res) => {
  handle(req, res).catch((err: unknown) => {
    if (res.headersSent) {
      res.destroy();
      return;
    }
    if (err instanceof HttpError) {
      const allow = (err as HttpError & { allow?: string }).allow;
      // Drain any unread body so the connection stays usable.
      req.resume();
      return sendError(res, err, allow ? { allow } : {});
    }
    console.error(err);
    sendError(res, new HttpError(500, 'internal_error', 'Internal server error.'));
  });
});
server.listen(port, () => console.log(`server listening on ${port}`));

let shuttingDown = false;
for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    if (shuttingDown) return;
    shuttingDown = true;
    server.close(() => {
      db.close();
      process.exit(0);
    });
    server.closeIdleConnections();
    setTimeout(() => {
      server.closeAllConnections();
    }, 2000).unref();
    setTimeout(() => process.exit(0), 4000).unref();
  });
}

