    const now = Date.now();
    const id = randomUUID();
    db.prepare(
      `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, progress, idempotency_key, payload_fingerprint, run_at, created_at, updated_at)
       VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, ?, ?, ?, ?)`,
    ).run(id, payload.input, payload.steps, payload.failAttempts, key, key === null ? null : fingerprint, now, now, now);
    return { status: 201, job: getJobRow(id)! };
  });
}

function workerUp(): boolean {
  const row = db.prepare('SELECT MAX(beat_at) AS beat FROM worker_heartbeat').get() as { beat: number | null };
  return row.beat !== null && Date.now() - row.beat <= HEARTBEAT_FRESH_MS;
}

function methodNotAllowed(allowed: string[]): never {
  throw Object.assign(new HttpError(405, 'method_not_allowed', 'Method not allowed.'), { allow: allowed.join(', ') });
}

async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  const method = req.method ?? 'GET';
  const isGet = method === 'GET' || method === 'HEAD';

  if (pathname === '/') {
    if (!isGet) methodNotAllowed(['GET']);
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8', 'cache-control': 'no-store' });
    res.end(method === 'HEAD' ? undefined : uiHtml);
    return;
  }
  if (pathname === '/health') {
    if (!isGet) methodNotAllowed(['GET']);
    return send(res, 200, { status: 'ok', worker: workerUp() ? 'up' : 'down' });
  }
  if (pathname === '/api/jobs') {
    if (method === 'POST') {
      const raw = await readBody(req);
      const { payload, key } = validate(req, raw);
      const { status, job } = createJob(payload, key);
      return send(res, status, toJob(job));
    }
    if (!isGet) methodNotAllowed(['GET', 'POST']);
    const rows = db.prepare('SELECT * FROM jobs ORDER BY seq DESC').all() as unknown as JobRow[];
    return send(res, 200, { jobs: rows.map(toJob) });
  }
  const m = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (m) {
    if (!isGet) methodNotAllowed(['GET']);
    let id: string;
    try {
      id = decodeURIComponent(m[1]!);
    } catch {
      throw new HttpError(404, 'not_found', 'Job not found.');
    }
    const row = getJobRow(id);
    if (!row) throw new HttpError(404, 'not_found', 'Job not found.');
    return send(res, 200, toJob(row));
  }
  throw new HttpError(404, 'not_found', 'Not found.');
}

const port = Number(process.env.PORT || 3000);
const server = createServer((req, res) => {
  handle(req, res).catch((err: unknown) => {
    if (res.headersSent) {
      res.destroy();
      return;
    }
    if (err instanceof HttpError) {
      const allow = (err as HttpError & { allow?: string }).allow;
      // Drain any unread body so the connection stays usable.
      req.resume();
      return sendError(res, err, allow ? { allow } : {});
    }
    console.error(err);
    sendError(res, new HttpError(500, 'internal_error', 'Internal server error.'));
  });
});
server.listen(port, () => console.log(`server listening on ${port}`));

let shuttingDown = false;
for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    if (shuttingDown) return;
    shuttingDown = true;
    server.close(() => {
      db.close();
      process.exit(0);
    });
    server.closeIdleConnections();
    setTimeout(() => {
      server.closeAllConnections();
    }, 2000).unref();
    setTimeout(() => process.exit(0), 4000).unref();
  });
}

